solution.solution.c:
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

struct scores
{
    size_t count;
    char name[16];
    int values[];
};

size_t scores_bytes(size_t count)
{
    return sizeof(struct scores) + count * sizeof(int);
}

struct scores *scores_new(const char *name, const int *values, size_t count)
{
    struct scores *s = malloc(scores_bytes(count));
    if (s == NULL)
        return NULL;
    s->count = count;
    strncpy(s->name, name, sizeof s->name - 1);
    s->name[sizeof s->name - 1] = '\0';
    if (count > 0)
        memcpy(s->values, values, count * sizeof(int));
    return s;
}

int scores_best(const struct scores *s)
{
    if (s->count == 0)
        return 0;
    int best = s->values[0];
    for (size_t i = 1; i < s->count; i++)
        if (s->values[i] > best)
            best = s->values[i];
    return best;
}

struct scores *scores_add(struct scores *s, int value)
{
    struct scores *bigger = realloc(s, scores_bytes(s->count + 1));
    if (bigger == NULL)
        return NULL;
    bigger->values[bigger->count++] = value;
    return bigger;
}

unitTests:
TEST("making a record") { int v[] = {40, 95, 60}; struct scores *s = scores_new("Ada", v, 3); CHECK(s != NULL); CHECK_EQ((int)s->count, 3); CHECK_STR(s->name, "Ada"); CHECK_EQ(s->values[1], 95); CHECK_EQ(scores_best(s), 95); free(s); }
TEST("long names are cut") { struct scores *s = scores_new("Bartholomew the Third", NULL, 0); CHECK_STR(s->name, "Bartholomew the"); CHECK_EQ(scores_best(s), 0); free(s); }
TEST("growing") { struct scores *s = scores_new("Bo", NULL, 0); for (int i = 1; i <= 100; i++) { s = scores_add(s, i * (i % 7)); CHECK(s != NULL); } CHECK_EQ((int)s->count, 100); CHECK_EQ(scores_best(s), 97 * 6); CHECK_EQ(s->values[99], 100 * 2); free(s); }
TEST("size") { CHECK_EQ((int)scores_bytes(0), (int)sizeof(struct scores)); CHECK_EQ((int)(scores_bytes(10) - scores_bytes(0)), (int)(10 * sizeof(int))); }

